import { z } from 'zod';

/**
 * Tool call definition representing an invocation generated by an LLM.
 */
export const ToolCallSchema = z.object({
  id: z.string().min(1, 'Tool call id must not be empty'),
  name: z.string().min(1, 'Tool name must not be empty'),
  arguments: z.record(z.unknown()).default({}),
});

export type ToolCall = z.infer<typeof ToolCallSchema>;

/**
 * Tool result representing the output returned by the host environment.
 */
export const ToolResultSchema = z.object({
  callId: z.string().min(1, 'Tool result callId must match a tool call id'),
  name: z.string().min(1, 'Tool name must not be empty'),
  output: z.unknown(),
  isError: z.boolean().optional().default(false),
  executionTimeMs: z.number().nonnegative().optional(),
});

export type ToolResult = z.infer<typeof ToolResultSchema>;

/**
 * Role of an agent message.
 */
export const MessageRoleSchema = z.enum(['system', 'user', 'assistant', 'tool']);
export type MessageRole = z.infer<typeof MessageRoleSchema>;

/**
 * Agent interaction message format.
 */
export const MessageSchema = z.object({
  role: MessageRoleSchema,
  content: z.string().nullable().optional(),
  name: z.string().optional(),
  toolCallId: z.string().optional(),
  toolCalls: z.array(ToolCallSchema).optional(),
});

export type Message = z.infer<typeof MessageSchema>;

/**
 * Token usage statistics for an interaction step.
 */
export const UsageSchema = z.object({
  promptTokens: z.number().int().nonnegative().optional(),
  completionTokens: z.number().int().nonnegative().optional(),
  totalTokens: z.number().int().nonnegative().optional(),
});

export type Usage = z.infer<typeof UsageSchema>;

/**
 * Finish reason for the LLM response.
 */
export const FinishReasonSchema = z.enum([
  'stop',
  'tool_calls',
  'length',
  'content_filter',
  'error',
]);

export type FinishReason = z.infer<typeof FinishReasonSchema>;

/**
 * LLM request prompt input captured in a step.
 */
export const StepInputSchema = z.object({
  messages: z.array(MessageSchema),
  model: z.string().optional(),
  temperature: z.number().optional(),
  maxTokens: z.number().optional(),
});

export type StepInput = z.infer<typeof StepInputSchema>;

/**
 * LLM response output recorded in a step.
 */
export const StepOutputSchema = z.object({
  message: MessageSchema,
  finishReason: FinishReasonSchema.optional().default('stop'),
  usage: UsageSchema.optional(),
});

export type StepOutput = z.infer<typeof StepOutputSchema>;

/**
 * Single interaction turn in an agent tape.
 */
export const TapeEntrySchema = z.object({
  id: z.string().min(1, 'Entry id is required'),
  step: z.number().int().nonnegative(),
  timestamp: z.string().datetime().optional(),
  input: StepInputSchema,
  output: StepOutputSchema,
  toolResults: z.array(ToolResultSchema).optional().default([]),
  metadata: z.record(z.unknown()).optional().default({}),
});

export type TapeEntry = z.infer<typeof TapeEntrySchema>;

/**
 * Tape metadata header.
 */
export const TapeMetadataSchema = z.object({
  id: z.string().min(1, 'Tape id is required'),
  name: z.string().min(1, 'Tape name is required'),
  description: z.string().optional().default(''),
  agentName: z.string().optional().default('agent'),
  createdAt: z.string().datetime().optional(),
  tags: z.array(z.string()).optional().default([]),
  custom: z.record(z.unknown()).optional().default({}),
});

export type TapeMetadata = z.infer<typeof TapeMetadataSchema>;

/**
 * Full tape fixture schema.
 */
export const TapeSchema = z.object({
  version: z.literal(1),
  metadata: TapeMetadataSchema,
  entries: z.array(TapeEntrySchema),
});

export type TapeData = z.infer<typeof TapeSchema>;

/**
 * Format Zod validation errors into human-readable strings.
 */
export function formatZodError(error: z.ZodError): string {
  return error.issues
    .map((issue) => `[${issue.path.join('.') || 'root'}]: ${issue.message}`)
    .join('; ');
}

/**
 * Safely parse tape data from an unknown input.
 */
export function parseTapeData(raw: unknown): TapeData {
  const parsed = TapeSchema.safeParse(raw);
  if (!parsed.success) {
    throw new Error(`Invalid tape data: ${formatZodError(parsed.error)}`);
  }
  return parsed.data;
}
